import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1228, own='cte_151.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)
H("922.d.3",3,"A ramp worker in a transportation practicum puts on a hi-vis vest, checks that her hearing protection fits and walks around the aircraft tug before starting it. She is:","understanding and applying proper safety techniques in the workplace",["hurrying to finish","avoiding her duties","guessing at the rules"],"Safety techniques.")
H("922.d.3",4,"Why do trained workers follow safety techniques even on routine jobs?","Most accidents happen when routine steps are skipped",["Routine jobs are never dangerous","Safety is only for new hires","Supervisors enjoy extra paperwork"],"Routine tasks still carry risk.")
H("922.d.1.A",3,"During a shift handoff, a dispatcher gives the next person a short, clear summary and points to the map to show the delay. She is:","using verbal and non-verbal communication in a clear, concise and effective manner",["rambling without a point","staying silent","using unclear slang"],"Clear communication.")
H("922.d.1.A",4,"Which message to a crew is the clearest and most concise?","\"Truck 4 loads at Dock B by 2:00 p.m.\"",["\"Um, you know, that truck thing, sometime later maybe.\"","\"Go get stuff done soon.\"","\"Somebody should probably do something at the docks.\""],"Specific details make it clear.")
H("922.d.1.B",3,"A trainee reads a fuel-use chart for three delivery routes, explains which route costs most and gives the numbers to her supervisor. She is:","analyzing, interpreting and communicating data and observations effectively",["hiding the chart","copying numbers blindly","ignoring the routes"],"Data communication.")
H("922.d.1.B",4,"When reporting data to a supervisor, a worker should:","state what the numbers show and what they mean",["list numbers with no explanation","report only guesses","avoid mentioning the source"],"Explain the meaning.")
H("922.d.1.C",3,"A trainee sees her supervisor's furrowed brow while she explains a delay and slows down to ask if more detail would help. She is:","observing and interpreting nonverbal cues to improve communication",["ignoring the supervisor","talking faster","leaving the room"],"Nonverbal cues.")
H("922.d.1.C",4,"A customer says 'fine' but crosses her arms and looks away. A skilled worker would:","ask a follow-up question to find out what is wrong",["assume everything is fine","walk away","finish the paperwork quickly"],"Words and body can differ.")
H("922.d.1.D",3,"A trainee repeats a pickup address back to the caller and asks, 'Is that the north entrance?' before dispatching a driver. She is:","applying active listening to obtain and clarify information",["assuming the address","interrupting the caller","skipping the check"],"Clarify.")
H("922.d.1.D",4,"Which habit is part of active listening?","Asking questions to confirm what was said",["Planning your answer while the speaker talks","Looking at a phone","Finishing the speaker's sentences"],"Active listening.")
H("922.d.2.A",3,"A trainee's cart will not start, so she checks the battery, then the cable, then the switch, using each result to decide what to test next. She is:","employing critical-thinking skills independently with increased fluency",["guessing randomly","giving up at once","changing everything at once"],"Critical thinking.")
H("922.d.2.A",4,"Critical thinking at work means a person:","weighs evidence before deciding",["follows the first idea","avoids hard problems","copies a coworker without checking"],"Weigh evidence.")
H("922.d.2.B",3,"A warehouse crew keeps blocking an aisle, so a trainee proposes painting loading zones and changing the pickup order. She is:","analyzing elements of a problem to develop creative and innovative solutions",["blaming the crew","ignoring the aisle","leaving the problem alone"],"Innovative solutions.")
H("922.d.2.B",4,"Before offering a creative fix, a worker should first:","identify the parts and the cause of the problem",["pick a favorite idea","wait for someone else","order new equipment"],"Analyze first.")
H("922.d.2.C",3,"A trainee tells a customer that the part has a worn bearing and needs a torque check, using the terms her program taught. She is:","using content, technical concepts and vocabulary when analyzing information",["using made-up words","avoiding terms","speaking in slang only"],"Technical vocabulary.")
H("922.d.2.C",4,"Why is accurate technical vocabulary valuable on a job site?","It prevents misunderstandings that cause errors",["It sounds fancier","It makes jobs take longer","It hides information"],"Accurate terms.")
H("922.d.3.A",3,"A trainee follows posted workplace rules about lockout of equipment and wears the required gear before servicing a conveyor. She is:","consistently following workplace safety rules and regulations",["skipping lockout","ignoring posted signs","wearing no gear"],"Safety rules.")
H("922.d.3.A",4,"Following safety rules is most important:","every time a task is performed",["only when watched","only on the first day","only when it is convenient"],"Always.")
H("922.d.3.B",3,"A trainee knows to stop work, tell her supervisor and fill out the incident form when a coworker is hurt by a loose pallet. She is:","demonstrating knowledge of procedures for reporting and handling accidents and safety incidents",["hiding the injury","leaving without telling anyone","fixing the pallet first"],"Reporting accidents.")
H("922.d.3.B",4,"Why must workers report every accident, even a small one?","Reports help prevent the same accident from happening again",["Reports create more paperwork","Small accidents never matter","Only managers need to know"],"Report it.")
H("922.d.4.A",3,"A trainee finishes each assigned task as directed, stays busy when work is slow and keeps a good attitude. She is:","demonstrating a positive, productive work ethic by performing assigned tasks as directed",["waiting to be told twice","doing the minimum","avoiding tasks"],"Work ethic.")
H("922.d.4.A",4,"A supervisor is away for the afternoon and a junior worker still stacks every pallet and cleans the bay. What does this show?","A strong, self-driven work ethic",["A need for constant supervision","A wish to avoid coworkers","A habit of cutting corners"],"Dependable effort without oversight.")
H("922.d.4.B",3,"A coworker asks a trainee to round up the hours on a shared log sheet, and she declines after considering what is fair and honest. She is:","applying ethical reasoning to make an ethical decision",["agreeing to avoid conflict","hiding the request","guessing"],"Ethical reasoning.")
H("922.d.4.B",4,"An ethical decision at work is one that is:","honest and fair to everyone affected",["quick and easy","profitable for one person","kept secret"],"Fair and honest.")
H("922.d.4.C",3,"A trainee checks that her driving hours and her paperwork follow all the laws and company rules before a trip. She is:","complying with all applicable rules, laws and regulations in a consistent manner",["skipping paperwork","bending rules","doing it only sometimes"],"Compliance.")
H("922.d.4.C",4,"Why do transportation workers have to follow laws and regulations?","They protect the safety of workers and the public",["They slow every job down","They only apply to managers","They are optional"],"Regulations.")
H("922.d.5.A",3,"A trainee in a supervised practicum carries out a service task, writes up what she did and reviews how it went with her mentor. She is:","conducting, documenting and evaluating learning activities in a supervised transportation setting",["skipping the write-up","working unsupervised","avoiding review"],"Supervised learning.")
H("922.d.5.A",4,"Documenting a learning activity helps a student because it:","creates a record she can review and improve from",["replaces practice","hides mistakes","adds no value"],"Documentation.")
H("922.d.5.B",3,"A trainee practices a new brake inspection method under supervision to move beyond basic skills for her chosen occupation. She is:","developing advanced technical knowledge and skills related to her occupational objective",["avoiding practice","staying at the basics","changing careers"],"Advanced knowledge.")
H("922.d.5.B",4,"Advanced skills in an occupation are usually built by:","repeated practice with feedback from experts",["one short lesson","reading one page","avoiding supervision"],"Practice and feedback.")
H("922.d.5.C",3,"A trainee's logbook shows she now completes a tire service in half the time with fewer errors than in the fall. She is:","demonstrating growth of technical skill competencies",["staying the same","hiding records","losing skills"],"Growth.")
H("922.d.5.C",4,"A good way to show skill growth over time is to:","compare earlier and later results",["compare to nothing","ignore the records","count only mistakes"],"Compare.")
H("922.d.5.D",3,"A trainee reviews her checklist and notes that she is strong at inspections but needs practice on documentation. She is:","evaluating strengths and weaknesses in technical skill proficiency",["ignoring her results","guessing","hiding weaknesses"],"Self-evaluation.")
H("922.d.5.D",4,"Knowing a weakness in a skill allows a student to:","plan practice where it is needed most",["avoid the skill","hide it","stop learning"],"Target practice.")
H("922.d.5.E",3,"A trainee saves a photo of a finished repair, a completed inspection form and a supervisor's note in a folder. She is:","collecting representative work samples",["throwing away records","avoiding documentation","saving random items"],"Work samples.")
H("922.d.5.E",4,"A representative work sample should:","show typical, quality work from the student",["be the worst example","be unrelated","be someone else's work"],"Representative.")
B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_151.jsonl"))
